head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05032";
scwin.form = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05032.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_bzCd_2", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '0'); } }, { id: "tr_97", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '0'); } }, { id: "if_bzCd_3", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '1'); } }, { id: "tr_105", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '1'); } }, { id: "if_bzCd", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '0' || (dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '1'); } }, { id: "if_bzCd_5", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '2'); } }, { id: "tr_239", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '2'); } }, { id: "if_bzCd_4", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '2' || (dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '3'); } }, { id: "if_bzCd_8", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '0' || (dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '2'); } }, { id: "if_bzCd_9", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '1' || (dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '3'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_351", entity: "dlt_readDataVOArrayUly", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return "주권발행기관_" + String(i + 1); } }, { childId: "ipt_ulyIsuCd", fn: function (v, i) { return String(v("ulyIsuCd")); } }, { childId: "ipt_ulyIsuNm", fn: function (v, i) { return String(v("ulyIsuNm")); } }, { childId: "ipt_ulyCompstRto", fn: function (v, i) { return String(v("ulyCompstRto")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_isuTotSum", fn: function () { return String((String(dma_readDataVO.get("isuShrs")) * String(dma_readDataVO.get("isuPrc")))); } },
        { childId: "ipt_isuTotPrc", fn: function () { return String((String(dma_readDataVO.get("isuShrs")) * String(dma_readDataVO.get("isuPrc")))); } },
        { childId: "ipt_isuTotPrcAdd", fn: function () { return String((String(dma_readDataVO.get("addIsuShrs")) * String(dma_readDataVO.get("isuPrc")))); } },
        { childId: "ipt_isuTotalAmt", fn: function () { return String((String(dma_readDataVO.get("isuShrs")) + String(dma_readDataVO.get("addIsuShrs")))); } },
        { childId: "ipt_isuTotalPrc", fn: function () { return String(((String(dma_readDataVO.get("isuShrs")) * String(dma_readDataVO.get("isuPrc"))) + (String(dma_readDataVO.get("addIsuShrs")) * String(dma_readDataVO.get("isuPrc"))))); } },
        { childId: "ipt_netIncm", fn: function () { return String((String(dma_readDataVO.get("totPubofrAmt")) - String(dma_readDataVO.get("fndSuplyAmt")))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.form = (document.ElwForm || { elements: [] });
        $c.util.getComponent('ipt_isuShtNm').setValue($c.util.getComponent("ipt_isuAbbrv1").getValue() + $c.util.getComponent("ipt_isuAbbrv2").getValue() + $c.util.getComponent("ipt_isuAbbrv3").getValue() + $c.util.getComponent("ipt_isuAbbrv4").getValue());
        $c.util.getComponent('ipt_engIsuShtNm').setValue($c.util.getComponent("ipt_isuEngAbbrv1").getValue() + $c.util.getComponent("ipt_isuEngAbbrv2").getValue() + $c.util.getComponent("ipt_isuEngAbbrv3").getValue() + $c.util.getComponent("ipt_isuEngAbbrv4").getValue());
        scwin.commaValueAll();
        scwin.setSelectDisabled(true);
        if ($c.util.getComponent('ipt_elwFinalPayVal').getValue()=== 0) {
            $c.util.getComponent('ipt_elwFinalPayVal').setValue("");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05032.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldfil05032: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_ElwPageUsrSearch_onclick
 * @description 「목록보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ElwPageUsrSearch_onclick = async function(e){
    try {
        await scwin.elwPageUsrSearch()
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil05032.btn_ElwPageUsrSearch_onclick" });
    }
};

/**
 * @method
 * @name __ev_2_btn_ElwPageUsrSearch_onclick
 * @description __ev_2_btn_ElwPageUsrSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__ev_2_btn_ElwPageUsrSearch_onclick = async function(e){
    try {
        await scwin.elwPageUsrSearch()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05032.__ev_2_btn_ElwPageUsrSearch_onclick' }); }
};

/**
 * @method
 * @name btn_ElwPageUsrSearch_2_onclick
 * @description 「목록보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ElwPageUsrSearch_2_onclick = async function(e){
    try {
        await scwin.elwPageUsrSearch()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05032.btn_ElwPageUsrSearch_2_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setSelectDisabled
 * @description set Select Disabled 처리
 * @param {*} isTrue isTrue
 * @returns {void}
 * @hidden N
 */
scwin.setSelectDisabled = function (isTrue) {
    $c.util.getComponent('slc_uinscribeYn').setDisabled(isTrue);
    $c.util.getComponent('slc_stdYn').setDisabled(isTrue);
    $c.util.getComponent('slc_fncUlyTpCd').setDisabled(isTrue);
    $c.util.getComponent('slc_fornInvstLmtObjIsuYn').setDisabled(isTrue);
    $c.util.getComponent('slc_elwRghtTpKindCd').setDisabled(isTrue);
    $c.util.getComponent('slc_elwRghtTpCd').setDisabled(isTrue);
    $c.util.getComponent('slc_elwExerTpCd').setDisabled(isTrue);
    $c.util.getComponent('slc_autoExerTpCd').setDisabled(isTrue);
    $c.util.getComponent('slc_halfwyRedmptYn').setDisabled(isTrue);
    $c.util.getComponent('slc_elwLstSetlMethdCd').setDisabled(isTrue);
    $c.util.getComponent('slc_elwObjIdxTpCd').setDisabled(isTrue);
    $c.util.getComponent('slc_leadcomMbrNo').setDisabled(isTrue);
    $c.util.getComponent('slc_transstkAgntCd').setDisabled(isTrue);
};

/**
 * @method
 * @name commaValueAll
 * @description comma Value All 처리
 * @returns {void}
 * @hidden N
 */
scwin.commaValueAll = function () {

    $c.fil.setComma($c.util.getComponent('ipt_isuPrc')); //   발행가격
    $c.fil.setComma($c.util.getComponent('ipt_isuShrs')); //   발행증권수
    $c.fil.setComma($c.util.getComponent('ipt_isuTotSum')); //   발행총액
    $c.fil.setComma($c.util.getComponent('ipt_elwConvRto')); //   ELW전환비율
    $c.fil.setComma($c.util.getComponent('ipt_elwUlyBasPrc')); //   ELW기초자산기초가격
    $c.fil.setComma($c.util.getComponent('ipt_elwExerPrc')); //   ELW행사가격
    $c.fil.setComma($c.util.getComponent('ipt_elwPrcUpPartcRt')); //   ELW가격상승참가율
    $c.fil.setComma($c.util.getComponent('ipt_elwCompnsRt')); //   ELW보상률
    $c.fil.setComma($c.util.getComponent('ipt_elwFinalPayVal')); //   ELW확정지급액
    $c.fil.setComma($c.util.getComponent('ipt_riskfreIntRt')); //   무위험이자율
    $c.fil.setComma($c.util.getComponent('ipt_elwDivRt')); //   ELW배당률
    $c.fil.setComma($c.util.getComponent('ipt_applVoltRto')); //   적용변동성비율
    $c.fil.setComma($c.util.getComponent('ipt_ordSpdRto')); //   호가스프레드
    $c.fil.setComma($c.util.getComponent('ipt_elwKoBasPrc')); //   조기종료발생기준가격/지수
    $c.fil.setComma($c.util.getComponent('ipt_isuExp'));    // 제반비용

    for(let i = 0 ; i < $c.util.getComponent('ipt_isuSchdlAmt').length  ; i++) {
        $c.fil.setComma($c.util.getComponent('ipt_isuSchdlAmt')[i]);
        $c.fil.setComma($c.util.getComponent('ipt_isuPrfmAmt')[i]);
    }
};

/**
 * @method
 * @name elwPageUsrSearch
 * @description elw Page Usr Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elwPageUsrSearch = async function () {
    scwin.form.bzCd.value   = BZ_USRLST ;

    if( $c.util.getComponent('ipt_isuNm') != null ) {
        $c.util.getComponent('ipt_isuNm').setValue("");
    }

    scwin.form.action       = '/list/elwPage.do';
    scwin.form.method.value = 'elwPageSearch';
    await moveUrl('/list/elwPage.do', {});

};
